// Each attack has its own footwork. Keys are phase, hip shift along the aim,
// knee bend, stance width and the amount of weight held over the lead foot.
P.HeroFootwork = (function () {
  var tracks = {
    knife: [[0,.02,.10,.09,.23],[.22,.24,.07,.23,.93],[.46,.19,.12,.24,.84],[.72,.04,.06,.12,.25]],
    nailgun: [[0,-.06,.09,.03,.18],[.20,-.12,.12,.03,.12],[.52,-.03,.04,.02,.05]],
    canister: [[0,-.06,.20,.17,.19],[.38,-.23,.08,.25,.06],[.59,.10,.06,.35,.61],[.73,.30,.23,.43,.97],[.85,.17,.15,.35,.73]],
    chain: [[0,-.09,.08,.15,.25],[.34,.08,.10,.34,.82],[.72,-.07,.06,.21,.37]],
    sledge: [[0,-.09,.13,.27,.30],[.42,-.21,-.035,.33,.12],[.50,.23,.39,.43,.97],[.64,.18,.30,.37,.82],[.83,.04,.13,.27,.54]],
    molotov: [[0,-.04,.02,.04,.08],[.47,-.07,-.04,.08,.17],[.70,.18,.04,.21,.91]],
    fireworks: [[0,-.06,.22,.09,.20],[.22,-.11,.20,.10,.16],[.53,-.11,-.08,.11,.32]],
    cable: [[0,.08,.06,.10,.46],[.22,-.11,.13,.11,.09],[.45,.08,.07,.18,.66],[.73,-.03,.07,.14,.28]],
    speargun: [[0,.08,.10,.28,.79],[.26,-.14,.13,.29,.12],[.64,-.10,.10,.29,.23]],
    extinguisher: [[0,-.04,.15,.24,.22],[.32,-.15,.19,.29,.10],[.78,-.10,.13,.24,.24]],
    sawblade: [[0,-.03,.04,.08,.26],[.24,.11,.05,.23,.73],[.57,.01,.09,.15,.30]],
    manhole: [[0,-.07,.18,.20,.26],[.43,-.14,.19,.28,.10],[.68,.21,.11,.34,.96],[.88,.10,.10,.28,.65]],
    torch: [[0,.03,.13,.14,.46],[.34,.14,.14,.23,.76],[.74,.17,.14,.24,.83]],
    olta: [[0,-.04,.06,.10,.21],[.37,.08,-.07,.12,.64],[.74,-.22,.23,.30,.08]],
    cardoor: [[0,-.10,.16,.21,.20],[.38,.12,.19,.38,.86],[.68,.17,.12,.35,.97],[.85,.03,.09,.29,.61]],
    slingshot: [[0,-.04,.06,.02,.20],[.43,-.13,.04,.04,.11],[.61,.09,.04,.11,.61]],
    chainsaw: [[0,-.08,.17,.21,.25],[.25,.16,.22,.32,.85],[.67,.19,.20,.32,.94],[.87,-.02,.10,.19,.40]],
    catchDisc: [[0,.11,.05,.10,.69],[.31,-.18,.19,.26,.12],[.63,-.08,.1,.20,.30]],
    grinder: [[0,-.12,.22,.34,.10],[.25,.22,.27,.42,.88],[.55,.21,.22,.43,.90],[.79,-.16,.24,.36,.12]],
    nailstorm: [[0,.07,.11,.24,.78],[.22,-.14,.14,.26,.13],[.52,.11,.18,.29,.77],[.77,-.12,.17,.27,.21]]
  };
  var neutral = [1,0,0,0,0];
  return function (k, phase, reduce, out) {
    var evolution = P.CFG.evolutions && P.CFG.evolutions[k.id];
    var keys = k.f && k.f.catchDisc ? tracks.catchDisc : tracks[k.id] || tracks[evolution && evolution.from];
    out.hip = out.bend = out.spread = out.plant = 0;
    if (!keys) return;
    var i = 1;
    while (i < keys.length && phase >= keys[i][0]) i++;
    var a = keys[i - 1], b = keys[i] || neutral, t = (phase - a[0]) / (b[0] - a[0]);
    t = t * t * (3 - 2 * t);
    var gain = (evolution ? 1.32 : 1 + 0.09 * (k.lv - 1)) * (reduce ? 0.40 : 1);
    out.hip = (a[1] + (b[1] - a[1]) * t) * gain;
    out.bend = (a[2] + (b[2] - a[2]) * t) * gain;
    out.spread = (a[3] + (b[3] - a[3]) * t) * gain;
    out.plant = a[4] + (b[4] - a[4]) * t;
  };
})();
